browser tool: // Infrastructure only; the model authors its own curated functions around this.
const [action,...args]=process.argv.slice(2);
try {
  const task=process.env.OMEGA_TASK_TAG?.split(':').at(-1);
  if(!task)throw Error('Run this helper inside an Omega eval shell (OMEGA_TASK_TAG).');
  const response=await fetch('http://127.0.0.1:8797/browser/tool',{
    method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({task,action,args})});
  const result=await response.json();
  if(!response.ok || !result.ok)throw Error(result.message || 'Browser operation failed');
  console.log(JSON.stringify(result.result));
}catch(error){console.error(error.message);process.exitCode=1;}

demo: #+TITLE: Ora procurement desk — live Omega

* Research Morocco and Europe
#+begin_task :id procurement :browser procurement :browser-mode headless
Read instructions.bl.org. Use the actual browser and your eval tool to generate and execute curated procurement-search functions, understand Ora Ventures, and deliver company.bl.org, search.bl.org, opportunities.bl.org and run-review.bl.org. Find external still-open notices in Morocco and Europe. Follow the evidence and uncertainty requirements in the instructions. No applications or messages.
#+end_task

* Deliverables
[[company.bl.org][Company brief]]
[[search.bl.org][Curated executable search]]
[[opportunities.bl.org][Opportunity review]]
[[run-review.bl.org][Run discrepancies and friction]]


=> :ok

